def find_minimum_spanning_tree(n, m, edges):
    if n == 1:
        return 0

    # Sort edges by weight
    edges.sort(key=lambda x: x[2])

    parent = list(range(n + 1))
    rank = [1] * (n + 1)

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
        else:
            parent[v_root] = u_root
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1
        return True

    total_weight = 0
    count = 0

    for edge in edges:
        u, v, w = edge
        if find(u) != find(v):
            union(u, v)
            total_weight += w
            count += 1
            if count == n - 1:
                break

    return total_weight if count == n - 1 else -1

