        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or not grid[i][j]:
            return
        grid[i][j] = False  # Mark as visited
        dfs(i-1, j)
        dfs(i+1, j)
        dfs(i, j-1)
        dfs(i, j+1)

