def exist(board: List[List[str]], word: str) -> bool:
    if not word:
        return True
    rows = len(board)
    if rows == 0:
        return False
    cols = len(board[0])

    def dfs(i, j, index, visited):
        if index == len(word) - 1:
            return True
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            ni = i + dx
            nj = j + dy
            if 0 <= ni < rows and 0 <= nj < cols:
                if board[ni][nj] == word[index + 1] and not visited[ni][nj]:
                    visited[ni][nj] = True
                    if dfs(ni, nj, index + 1, visited):
                        return True
                    visited[ni][nj] = False
        return False

    for i in range(rows):
        for j in range(cols):
            if board[i][j] == word[0]:
                visited = [[False for _ in range(cols)] for _ in range(rows)]
                visited[i][j] = True
                if dfs(i, j, 0, visited):
                    return True
    return False

