def determine_capital(N: int, M: int, A: int, B: int, residents: List[int], roads: List[Tuple[int, int]]) -> int:
    # Build the adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v in roads:
        adj[u].append(v)
        adj[v].append(u)

    # Function to compute shortest distances from a start city using BFS
    def bfs(start: int) -> List[int]:
        distances = [-1] * (N + 1)
        queue = deque()
        distances[start] = 0
        queue.append(start)
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if distances[v] == -1:
                    distances[v] = distances[u] + 1
                    queue.append(v)
        return distances

    # Compute distances for both candidate capitals
    dist_a = bfs(A)
    dist_b = bfs(B)

    # Calculate the maximum travel distance for each capital
    max_a = 0
    for i in range(1, N + 1):
        d = dist_a[i]
        max_a = max(max_a, d * residents[i - 1])

    max_b = 0
    for i in range(1, N + 1):
        d = dist_b[i]
        max_b = max(max_b, d * residents[i - 1])

    # Determine the better capital
    if max_a < max_b:
        return A
    elif max_b < max_a:
        return B
    else:
        return min(A, B)

