from typing import List

def three_sum(arr: List[int], target: int) -> List[List[int]]:
    sorted_arr = sorted(arr)
    result = []
    n = len(sorted_arr)
    for i in range(n):
        if i > 0 and sorted_arr[i] == sorted_arr[i-1]:
            continue
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = sorted_arr[i] + sorted_arr[left] + sorted_arr[right]
            if current_sum == target:
                result.append([sorted_arr[i], sorted_arr[left], sorted_arr[right]])
                # Skip duplicates for left
                while left < right and sorted_arr[left] == sorted_arr[left+1]:
                    left += 1
                # Skip duplicates for right
                while left < right and sorted_arr[right] == sorted_arr[right-1]:
                    right -= 1
                left += 1
                right -= 1
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return result

def sum_sub_squares_optimized(matrix, k):
    n = len(matrix)
    # Create a prefix sum matrix with an extra row and column for easier indexing
    prefix = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            prefix[i][j] = matrix[i-1][j-1] + prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1]

    result = []
    for i in range(n - k + 1):
        row = []
        for j in range(n - k + 1):
            sum_val = prefix[i + k][j + k] - prefix[i][j + k] - prefix[i + k][j] + prefix[i][j]
            row.append(sum_val)
        result.append(row)

    return result

