def calculate_combinations(n: int, r: int) -> int:
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    dp = [0] * (r + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(min(i, r), 0, -1):
            dp[j] += dp[j - 1]
    return dp[r]

from typing import List, Optional, Tuple

def search_in_matrix(mat: List[List[int]], key: int) -> Optional[Tuple[int, int]]:
    rows = len(mat)
    if rows == 0:
        return None
    cols = len(mat[0])
    row, col = 0, cols - 1
    while row < rows and col >= 0:
        current = mat[row][col]
        if current == key:
            return (row, col)
        elif current > key:
            col -= 1
        else:
            row += 1
    return None

def findRepeatedPhrases(text, phraseLength):
    words = text.split()
    phrase_counts = {}
    repeated_phrases = []

    for i in range(len(words) - phraseLength + 1):
        phrase = ' '.join(words[i:i+phraseLength])
        if phrase in phrase_counts:
            phrase_counts[phrase] += 1
        else:
            phrase_counts[phrase] = 1
            repeated_phrases.append(phrase)

    # Filter to include only phrases that appear more than once
    result = [phrase for phrase in repeated_phrases if phrase_counts[phrase] > 1]
