def reverse_number(n: int) -> int:
    if n == 0:
        return 0
    is_negative = False
    if n < 0:
        is_negative = True
        n = -n
    reversed_num = 0
    while n > 0:
        last_digit = n % 10
        reversed_num = reversed_num * 10 + last_digit
        n = n // 10
    if is_negative:
        reversed_num = -reversed_num
    return reversed_num

