class FenwickTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (self.n + 1)
        self.arr = arr.copy()
        for i in range(self.n):
            self._update(i + 1, arr[i])

    def _update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def _query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

    def update(self, idx, value):
        delta = value - self.arr[idx]
        self.arr[idx] = value
        self._update(idx + 1, delta)

    def query(self, idx):
        return self._query(idx + 1)

