def trap(arr):
    left = 0
    right = len(arr) - 1
    max_left = 0
    max_right = 0
    result = 0
    while left < right:
        if arr[left] < arr[right]:
            if arr[left] > max_left:
                max_left = arr[left]
            else:
                result += max_left - arr[left]
            left += 1
        else:
